<?php
$tests['T-01']=function(){ global $fixture; foreach($fixture['users'] as $c=>$uid) {ctx($c); $dealer=in_array($c,['wholesale','vip']); foreach($fixture['products'] as $n=>$id) { $p=wc_get_product($id); $v=expected($n,$dealer); $want=$n==='variable'?[100,'','']:[$v,$v,$n==='on_sale'?80:'']; if(!$dealer&&$n==='on_sale')$want=[80,100,80]; tuple([$p->get_price(),$p->get_regular_price(),$p->get_sale_price()],$want,"$c/$n/getters"); $html=$p->get_price_html(); $text=text_html($html); $expected=$n==='variable'?text_html(wc_format_price_range(wc_price($dealer?90:100),wc_price($dealer?108:120))):text_html(!$dealer&&$n==='on_sale'?wc_format_sale_price(wc_price(100),wc_price(80)):wc_price($v)); eq($text,$expected,"$c/$n/html"); check(str_contains($html,'woocommerce-Price-amount'),"$c/$n Woo wrapper"); } } };
$tests['T-02']=function(){global $fixture;foreach($fixture['users']as$c=>$uid){ctx($c);foreach($fixture['products']as$n=>$id){if($n==='variable')continue;foreach([1,5]as$q){$v=expected($n,in_array($c,['wholesale','vip']),$q);foreach(cart($id,$q)[1]as$i=>$row)tuple($row,[$v,$v,$v*$q,$v*$q,$v*$q],"$c/$n/q$q/pass$i");}}}};
$tests['T-03']=function(){ctx('wholesale');foreach(['percent'=>90,'discount'=>85,'on_sale'=>80]as$n=>$v){$fresh=wc_get_product(pid($n));eq($fresh->get_price(),$v,$n.' fresh');foreach(cart(pid($n),5)[1]as$row)tuple($row,[$v,$v,$v*5,$v*5,$v*5],$n.' reused');}};
$tests['T-04']=function(){ctx('wholesale');foreach([1=>90,4=>90,5=>75,6=>75]as$q=>$v){eq(CEWP\Pricing::resolve(100,pid('tier'),0,$q),$v,'resolver qty'.$q);foreach(cart(pid('tier'),$q)[1]as$row)tuple($row,[$v,$v,$v*$q,$v*$q,$v*$q],'cart qty'.$q);}eq(wc_get_product(pid('tier'))->get_price(),90,'catalog qty1');};
$tests['T-05']=function(){global $wpdb;ctx('wholesale');$t=CEWP\Database::t('prices');$wpdb->delete($t,['product_id'=>pid('variable')]);foreach([[0,90,1],[0,75,5],[pid('variation_small'),85,1],[pid('variation_small'),70,5]]as[$vid,$v,$q])$wpdb->insert($t,rule(pid('variable'),'fixed',$v,'wholesale',['variation_id'=>$vid,'min_qty'=>$q]));foreach([1,5]as$q){foreach(['variation_small'=>$q===1?85:70,'variation_large'=>$q===1?90:75]as$n=>$v){eq(CEWP\Pricing::resolve(100,pid('variable'),pid($n),$q),$v,$n.' resolver');foreach(cart(pid($n),$q)[1]as$row)eq($row[1],$v,$n.' cart');}}$wpdb->update($t,['min_qty'=>10],['variation_id'=>pid('variation_small')]);eq(CEWP\Pricing::resolve(100,pid('variable'),pid('variation_small'),5),75,'ineligible exact falls back');};
$tests['T-06']=function(){foreach(['guest','retail','wholesale','vip']as$c){ctx($c);$dealer=in_array($c,['wholesale','vip']);$p=wc_get_product(pid('variable'));$a=$p->get_variation_prices();foreach(['variation_small'=>$dealer?90:100,'variation_large'=>$dealer?108:120]as$n=>$v){foreach(['price','regular_price','sale_price']as$channel)eq($a[$channel][pid($n)],$v,"$c/$n/$channel");$child=wc_get_product(pid($n));eq($child->get_sale_price(),'','empty sale');check(!str_contains($child->get_price_html(),'<del'),'no false sale');}}};
$tests['T-07']=function(){global $wpdb;ctx('wholesale');foreach([0,'0','0.0000',null,'']as$cap){$wpdb->update(CEWP\Database::t('prices'),['sale_price'=>$cap===''?null:$cap],['product_id'=>pid('percent')]);eq(CEWP\Pricing::resolve(100,pid('percent')),90,'resolver cap '.json_encode($cap));$p=wc_get_product(pid('percent'));tuple([$p->get_price(),$p->get_regular_price(),$p->get_sale_price()],[90,90,''],'getter cap');foreach(cart(pid('percent'),1)[1]as$row)eq($row[1],90,'cart cap');}};
$tests['T-08']=function(){global $wpdb;ctx('wholesale');foreach([70=>70,90=>90,100=>90]as$cap=>$v){$wpdb->update(CEWP\Database::t('prices'),['sale_price'=>$cap],['product_id'=>pid('percent')]);eq(CEWP\Pricing::resolve(100,pid('percent')),$v,'positive cap');eq(wc_get_product(pid('percent'))->get_price(),$v,'getter');foreach(cart(pid('percent'),1)[1]as$row)eq($row[1],$v,'cart');}};
$tests['T-09']=function(){global $wpdb;ctx('wholesale');foreach([0,'0','0.0000',null,'']as$cap){$wpdb->update(CEWP\Database::t('prices'),['price_value'=>0,'sale_price'=>$cap===''?null:$cap],['product_id'=>pid('fixed')]);eq(CEWP\Pricing::resolve(100,pid('fixed')),0,'matched zero');$p=wc_get_product(pid('fixed'));tuple([$p->get_price(),$p->get_regular_price(),$p->get_sale_price()],[0,0,''],'zero getters');foreach(cart(pid('fixed'),1)[1]as$row)tuple($row,[0,0,0,0,0],'zero cart');}};
$tests['T-10']=function(){global $wpdb;ctx('wholesale');$t=CEWP\Database::t('prices');foreach(['percent_discount','fixed','none']as$type){if($type==='none')$wpdb->delete($t,['product_id'=>pid('on_sale')]);else $wpdb->update($t,['price_type'=>$type,'price_value'=>$type==='fixed'?120:10],['product_id'=>pid('on_sale')]);$p=wc_get_product(pid('on_sale'));tuple([$p->get_price(),$p->get_regular_price(),$p->get_sale_price()],$type==='none'?[80,100,80]:[80,80,80],'ceiling '.$type);foreach(cart(pid('on_sale'),1)[1]as$row)eq($row[1],80,'charge ceiling');}};
$tests['T-11']=function(){foreach(['guest','retail','wholesale','vip']as$c)foreach([true,false,null]as$flag)foreach([1,5]as$q){ctx($c);$flag===null?delete_option('cewp_settings'):update_option('cewp_settings',['disallow_coupons'=>$flag]);$dealer=in_array($c,['wholesale','vip']);$allowed=!$dealer||$flag===false;$v=$dealer?60:100;[$applied,$passes]=cart(pid('fixed'),$q,true);eq($applied,$allowed,"$c coupon ".json_encode($flag));foreach($passes as$row)tuple($row,[$v,$v,$v*$q,$v*$q*($allowed?.9:1),$v*$q*($allowed?.9:1)],'coupon totals');eq(apply_filters('woocommerce_coupon_is_valid',false,new WC_Coupon('char-ten'),new WC_Discounts(WC()->cart)),false,'invalid remains invalid');}};
$tests['T-26']=function(){foreach(['wholesale','retail','vip','wholesale','retail']as$c){ctx($c);foreach([5,1,5]as$q)foreach(['tier','percent','variation_small']as$n){$v=expected($n,$c!=='retail',$q);foreach(cart(pid($n),$q)[1]as$row)eq($row[1],$v,"$c/$q/$n");}}};
